package com.aac.ieojwo.location.domain;
import com.aac.ieojwo.common.domain.BaseTimeEntity;import com.aac.ieojwo.user.domain.AacUser;import jakarta.persistence.*;import java.time.LocalTime;
@Entity @Table(name="saved_places")public class SavedPlace extends BaseTimeEntity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="aac_user_id",nullable=false)private AacUser user;@Column(nullable=false,length=80)private String name;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private PlaceType placeType;@Column(length=300)private String address;@Column(nullable=false)private double latitude;@Column(nullable=false)private double longitude;@Column(nullable=false)private int radiusMeters;private LocalTime activeFrom;private LocalTime activeTo;@Column(nullable=false)private boolean active;protected SavedPlace(){}public static SavedPlace create(AacUser u,String n,PlaceType t,String a,double lat,double lon,int radius,LocalTime from,LocalTime to){SavedPlace p=new SavedPlace();p.user=u;p.apply(n,t,a,lat,lon,radius,from,to);p.active=true;return p;}public void apply(String n,PlaceType t,String a,double lat,double lon,int r,LocalTime f,LocalTime to){name=n.trim();placeType=t;address=a==null||a.isBlank()?null:a.trim();latitude=lat;longitude=lon;radiusMeters=r;activeFrom=f;activeTo=to;}public void deactivate(){active=false;}public boolean activeAt(LocalTime now){if(!active)return false;if(activeFrom==null||activeTo==null)return true;return !now.isBefore(activeFrom)&&!now.isAfter(activeTo);}public Long getId(){return id;}public AacUser getUser(){return user;}public String getName(){return name;}public PlaceType getPlaceType(){return placeType;}public String getAddress(){return address;}public double getLatitude(){return latitude;}public double getLongitude(){return longitude;}public int getRadiusMeters(){return radiusMeters;}public LocalTime getActiveFrom(){return activeFrom;}public LocalTime getActiveTo(){return activeTo;}}
